sys_ux_data_broker_transform.script:
function transform(input) {
    // Get KPI configuration from system property
    var kpiPropertyName = 'sam.foundation.current.location.kpi';
    var kpiProperty = gs.getProperty(kpiPropertyName);

    // Parse the KPI property to get table and field
    var tableName = '';
    var fieldName = '';

    try {
        if (kpiProperty) {
            var kpiConfigs = JSON.parse(kpiProperty);

            // Find the configuration for duplicate locations
            for (var i = 0; i < kpiConfigs.length; i++) {
                var config = kpiConfigs[i];
                if (config.kpi === "Duplicate Location") {
                    tableName = config.table;
                    fieldName = config.field;
                    break;
                }
            }
        }
    } catch (e) {
        gs.error('Error parsing KPI property ' + kpiPropertyName + ': ' + e);
        return [];
    }

    // Validate that we have both table and field
    if (!tableName || !fieldName) {
        gs.error('Missing table or field in KPI configuration: ' + kpiPropertyName);
        return [];
    }

    var totalDuplicateCount = 0;

    // Query the specified table and group by the specified field
    var gr = new GlideAggregate(tableName);
    gr.addAggregate('COUNT', fieldName);
    gr.groupBy(fieldName);
    gr.addHaving('COUNT', '>', 1); // Filter records with duplicates
    gr.query();

    // Calculate total duplicate records
    while (gr.next()) {
        var count = parseInt(gr.getAggregate('COUNT', fieldName), 10);
        totalDuplicateCount += (count - 1);
    }

    // Construct response following the required schema
    return [
        {
            "data": [
                {
                    "value": totalDuplicateCount,
                    "change": "0",
                    "changePercent": "0"
                }
            ],
            "metadata": {
                "eventData": {
                    "indicatorSysid": "fb007202d7130100b96d45a3ce6103b4"
                },
                "previousScoreDate": "1642809600000",
                "dataSourceLabel": "Number of duplicate locations",
                "changeArrow": "steady",
                "scoreDate": "1642896000000",
                "filterQuery": "nameISNOTEMPTY",
                "aggregate": {
                    "fieldType": "decimal"
                },
                "format": {
                    "unitFormat": "{0}",
                    "frequency": "daily",
                    "precision": 0
                }
            },
            "sparkline": {
                "data": [
                    {
                        "timestamp": "1637798400000",
                        "value": totalDuplicateCount
                    }
                ],
                "metadata": {
                    "eventData": {
                        "indicatorSysid": "fb007202d7130100b96d45a3ce6103b4"
                    },
                    "dataSourceLabel": "Number of duplicate locations",
                    "series": [
                        {
                            "label": "Duplicate Locations",
                            "id": "value",
                            "type": "value"
                        }
                    ],
                    "aggregate": {
                        "fieldType": "decimal"
                    },
                    "format": {
                        "unitFormat": "{0}",
                        "frequency": "daily",
                        "precision": 0
                    }
                }
            }
        }
    ];
}
